#include <stack>
#include <iostream>

int main() {
    std::stack<int> st;
    st.push(10);
    st.push(20); // Top element is 20

    // Modify the top element in place
    st.top() = 77; // Changes 20 to 77

    st.push(4);

    // Output: 4 77 10
    while (!st.empty()) {
        std::cout << st.top() << " ";
        st.pop();
    }
}
